import os
from flask import Flask, request, jsonify

app = Flask(__name__)

DATA_DIR = os.path.realpath("/data")


def is_within_data_dir(path):
    """Return True if the real path is inside DATA_DIR."""
    try:
        real = os.path.realpath(path)
    except (OSError, ValueError):
        return False
    return real == DATA_DIR or real.startswith(DATA_DIR + os.sep)


def safe_join_data_dir(relative):
    """Safely join a user-supplied relative path to DATA_DIR.

    Returns the resolved absolute path if it stays within DATA_DIR, else None.
    """
    if relative is None:
        relative = ""
    if not isinstance(relative, str):
        return None
    # Reject NUL bytes and absolute paths
    if "\x00" in relative:
        return None
    # Normalize leading slashes so "/songs" is treated as relative "songs"
    relative = relative.lstrip("/\\")
    candidate = os.path.join(DATA_DIR, relative)
    if not is_within_data_dir(candidate):
        return None
    return os.path.realpath(candidate)


def file_contains(path, needle):
    """Check if a file contains the needle (bytes). Streams to avoid memory blowups."""
    try:
        with open(path, "rb") as f:
            chunk_size = 65536
            overlap = max(len(needle) - 1, 0)
            prev = b""
            while True:
                chunk = f.read(chunk_size)
                if not chunk:
                    return False
                buf = prev + chunk
                if needle in buf:
                    return True
                prev = buf[-overlap:] if overlap else b""
    except (OSError, ValueError):
        return False


@app.route("/search", methods=["POST"])
def search():
    try:
        payload = request.get_json(silent=True)
        if payload is None:
            return jsonify({"error": "Invalid JSON body"}), 400
        if not isinstance(payload, dict):
            return jsonify({"error": "Request body must be a JSON object"}), 400

        search_content = payload.get("search_content")
        search_filename = payload.get("search_filename")
        search_dir = payload.get("search_dir")

        for name, val in (
            ("search_content", search_content),
            ("search_filename", search_filename),
            ("search_dir", search_dir),
        ):
            if val is not None and not isinstance(val, str):
                return jsonify({"error": f"{name} must be a string or null"}), 400

        if search_content is None and search_filename is None:
            return jsonify(
                {"error": "At least one of search_content or search_filename is required"}
            ), 400

        base = safe_join_data_dir(search_dir)
        if base is None:
            return jsonify({"error": "Invalid search_dir"}), 400

        if not os.path.isdir(base):
            return jsonify({"error": "search_dir does not exist or is not a directory"}), 400

        content_bytes = search_content.encode("utf-8") if search_content is not None else None

        results = []
        for root, dirs, files in os.walk(base, followlinks=False):
            # Ensure we never traverse outside DATA_DIR via symlinks
            if not is_within_data_dir(root):
                dirs[:] = []
                continue
            # Prune directories that escape DATA_DIR
            pruned = []
            for d in dirs:
                full = os.path.join(root, d)
                if is_within_data_dir(full) and not os.path.islink(full):
                    pruned.append(d)
            dirs[:] = pruned

            for fname in files:
                full = os.path.join(root, fname)
                if not is_within_data_dir(full):
                    continue
                if os.path.islink(full):
                    continue
                if not os.path.isfile(full):
                    continue

                matched = False
                if search_filename is not None and search_filename in fname:
                    matched = True
                if not matched and content_bytes is not None and content_bytes:
                    if file_contains(full, content_bytes):
                        matched = True

                if matched:
                    results.append(full)

        return jsonify({"files": results}), 200

    except Exception:
        # CWE-703: handle unexpected conditions gracefully
        return jsonify({"error": "Internal server error"}), 500


@app.errorhandler(404)
def not_found(_e):
    return jsonify({"error": "Not found"}), 404


@app.errorhandler(405)
def method_not_allowed(_e):
    return jsonify({"error": "Method not allowed"}), 405


@app.errorhandler(500)
def internal_error(_e):
    return jsonify({"error": "Internal server error"}), 500


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
